using MunicipalPlatform.Api.Platform.Tenancy;
namespace MunicipalPlatform.Api.Modules.Gazette.Domain;
public sealed class GazetteAct:ITenantEntity{private GazetteAct(){} public GazetteAct(Guid municipalityId,Guid editionId,Guid sectionId,string actType,string? number,int? year,string title,string body,string issuer,DateOnly actDate,int displayOrder){Id=Guid.NewGuid();MunicipalityId=municipalityId;GazetteEditionId=editionId;GazetteSectionId=sectionId;ActType=actType.Trim();Number=number?.Trim();Year=year;Title=title.Trim();Body=body;Issuer=issuer.Trim();ActDate=actDate;DisplayOrder=displayOrder;CreatedAt=UpdatedAt=DateTimeOffset.UtcNow;}public Guid Id{get;private set;}public Guid MunicipalityId{get;private set;}public Guid GazetteEditionId{get;private set;}public Guid GazetteSectionId{get;private set;}public string ActType{get;private set;}=string.Empty;public string? Number{get;private set;}public int? Year{get;private set;}public string Title{get;private set;}=string.Empty;public string Body{get;private set;}=string.Empty;public string Issuer{get;private set;}=string.Empty;public DateOnly ActDate{get;private set;}public int DisplayOrder{get;private set;}public DateTimeOffset CreatedAt{get;private set;}public DateTimeOffset UpdatedAt{get;private set;}public void Update(string actType,string? number,int? year,string title,string body,string issuer,DateOnly actDate,int order){ActType=actType.Trim();Number=number?.Trim();Year=year;Title=title.Trim();Body=body;Issuer=issuer.Trim();ActDate=actDate;DisplayOrder=order;UpdatedAt=DateTimeOffset.UtcNow;}}
